-- sism-analytics @DataJpaTest 专用建表（H2；与 V107 生产态对齐）
-- 生产迁移 V107__create_analytics_report_tables.sql 的 H2 等价版本：
-- BIGSERIAL PRIMARY KEY → BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
-- （H2 无 BIGSERIAL；IDENTITY 语义与 PostgreSQL 序列默认值等价）
-- DROP IF EXISTS 保证多测试上下文共享同一内存库时可重复执行

DROP TABLE IF EXISTS analytics_report;
DROP TABLE IF EXISTS analytics_dashboard;
DROP TABLE IF EXISTS data_export;

CREATE TABLE analytics_report (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_name     VARCHAR(255) NOT NULL,
    report_type     VARCHAR(50)  NOT NULL,
    report_format   VARCHAR(50)  NOT NULL,
    status          VARCHAR(50)  NOT NULL,
    file_path       VARCHAR(1000),
    file_size       BIGINT,
    creator_id      BIGINT,
    generation_time TIMESTAMP,
    report_params   TEXT,
    description     VARCHAR(1000),
    error_message   VARCHAR(1000),
    is_deleted      BOOLEAN NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMP NOT NULL,
    updated_at      TIMESTAMP
);

CREATE TABLE analytics_dashboard (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dashboard_name VARCHAR(255) NOT NULL,
    description    VARCHAR(1000),
    user_id        BIGINT NOT NULL,
    is_public      BOOLEAN NOT NULL DEFAULT FALSE,
    config         TEXT,
    is_deleted     BOOLEAN NOT NULL DEFAULT FALSE,
    created_at     TIMESTAMP NOT NULL,
    updated_at     TIMESTAMP
);

CREATE TABLE data_export (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_name        VARCHAR(255) NOT NULL,
    task_type        VARCHAR(50)  NOT NULL,
    export_format    VARCHAR(50)  NOT NULL,
    status           VARCHAR(50)  NOT NULL,
    result_file_path VARCHAR(1000),
    result_file_size BIGINT,
    creator_id       BIGINT NOT NULL,
    created_at       TIMESTAMP NOT NULL,
    start_time       TIMESTAMP,
    end_time         TIMESTAMP,
    error_log        VARCHAR(1000),
    task_params      TEXT,
    is_deleted       BOOLEAN NOT NULL DEFAULT FALSE,
    updated_at       TIMESTAMP
);
